struct Phase{budget:Arc<Budget>,ok:bool}impl Drop for Phase{fn drop(&mut self){if !self.ok{self.budget.keep_failed_scratch()}}}

fn schema_charge(hints:&crate::value_schema_policy::SchemaHints)->Option<usize>{let mut charge=Some(0usize);hints.visit_storage(|rows|charge=rows.iter().try_fold(0usize,|n,(owner,name)|n.checked_add(2048)?.checked_add(owner.capacity())?.checked_add(name.capacity())));charge}
