 let mut selected=Vec::new();let mut emitted=HashSet::new();for row in rows{retained.checkpoint()?;if !row.rel.starts_with("code/")||scope.exempt(&row.rel){continue}kc::reserve(&mut retained,||row.rule.len().checked_add(row.rel.len())?.checked_mul(4)?.checked_add(2048))?;emitted.try_reserve(1).map_err(|_|retained.allocation_failed())?;if !emitted.insert((row.rule,row.rel.clone(),row.line)){continue}kc::row(&mut retained,&mut selected)?;selected.push(row);}
 enum Resolved{Site(String),Allow(AllowUse)}let mut resolved=Vec::new();fund::reserve_append(&phase.budget,poll,&mut resolved,selected.len())?;for _ in &selected{resolved.push(None);}let mut digests=BTreeMap::new();if !pages.for_each(&mut|relative,views|{fund::checked(&phase.budget,poll)?;if !crate::captured_raw_file::is_code_dm(relative)||scope.exempt(relative){return Err("stored ALLOW/source row escaped selected CODE".into())}let file=views.source_file()?;if file.rel!=relative{return Err("stored source row original path differs".into())}let raw=file.raw();let mut temporary=crate::captured_allow_annotations::PatternOperation{budget:views.allocation_budget(&phase.budget),poll,patterns};let mut used=false;for(index,row)in selected.iter().enumerate(){temporary.checkpoint()?;if row.rel!=relative{continue}if resolved[index].is_some()||row.line==0||row.line>raw.num_lines(){return Err("stored original declaration row missing or repeated".into())}resolved[index]=Some(if let Some(keep)=crate::allow::kept_using(file,row.line,"stored_refs",&mut temporary)?{used=true;let code=keep.code.unwrap_or_default();phase.budget.charge(code.capacity()).map_err(|m|oom(root,m))?;Resolved::Allow(AllowUse{rel:kc::own(&mut retained,relative)?,line:u32::try_from(keep.line).map_err(|_|retained.overflow())?,name:kc::own(&mut retained,"stored_refs")?,code})}else{let text=raw.line(row.line);kc::reserve(&mut temporary,||text.len().checked_mul(4)?.checked_add(256))?;let text=crate::util::normalize_ws(text);phase.budget.charge(text.capacity()).map_err(|m|oom(root,m))?;Resolved::Site(text)});}if used{kc::reserve(&mut retained,||Some(2048))?;digests.insert(kc::own(&mut retained,relative)?,crate::captured_raw_file::source_allow_digest(file));}Ok(true)})?{return Err("stored ALLOW/source phase stopped before actual selected CODE EOF".into())}
